INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Prix d''un site internet à La Réunion : le vrai coût', 'prix-site-internet-reunion', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'Sites web et landing', '990 € ou 5 000 € ? On détaille poste par poste ce que vous payez vraiment pour un site internet à La Réunion, maintenance et nom de domaine compris.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Le prix d''un site dépend de cinq postes : la conception, les contenus, la technique, le nom de domaine avec l''hébergement, et la maintenance.</li> <li>Chez DIGITA, une page de vente coûte 499 €, un site vitrine 990 € puis 49 €/mois, une boutique en ligne à partir de 2 490 €.</li> <li>Avant de signer, vérifiez trois choses : à qui appartient le nom de domaine, ce que couvre la maintenance et la durée de l''engagement.</li> </ul> </div> <p>« Combien coûte un site internet ? » C''est souvent la première question d''un dirigeant réunionnais, et la réponse « ça dépend » ne l''aide pas. Deux devis peuvent aller de quelques centaines à plusieurs milliers d''euros pour un résultat qui semble identique à l''écran. La différence se cache dans ce qui est compris, ou pas, dans le prix.</p> <p>Ce guide détaille ce que vous payez vraiment, les frais qui reviennent chaque année et les pièges à repérer dans un devis. Nous y donnons aussi nos propres prix, pour que vous ayez un point de comparaison concret.</p> <h2>Ce que vous payez vraiment : les 5 postes d''un site</h2> <p>Un site internet n''est pas un seul produit. C''est l''addition de cinq postes, que les prestataires regroupent ou détaillent chacun à leur façon.</p> <table class="table-article"> <thead><tr><th>Poste</th><th>Ce qu''il comprend</th><th>Payé</th><th>La question à poser</th></tr></thead> <tbody> <tr><td>Conception</td><td>Structure des pages, maquette, design adapté au mobile</td><td>Une fois</td><td>Le design est-il fait pour moi ou tiré d''un modèle ?</td></tr> <tr><td>Contenus</td><td>Textes, photos, logo, vidéos</td><td>Une fois</td><td>Qui écrit les textes et fournit les photos ?</td></tr> <tr><td>Technique</td><td>Mise en ligne, formulaire, sécurité (HTTPS), vitesse, référencement de base</td><td>Une fois</td><td>Google Analytics et la Search Console sont-ils branchés ?</td></tr> <tr><td>Domaine et hébergement</td><td>L''adresse (votre-entreprise.re ou .fr) et le serveur qui affiche le site</td><td>Chaque année</td><td>Le nom de domaine est-il enregistré à mon nom ?</td></tr> <tr><td>Maintenance</td><td>Mises à jour, sauvegardes, petites modifications, assistance</td><td>Chaque mois</td><td>Combien de modifications sont comprises, et en combien de temps ?</td></tr> </tbody> </table> <p>Un devis bas qui ne parle ni des contenus ni de la maintenance n''est pas forcément moins cher. Il reporte simplement ces coûts à plus tard, ou sur votre temps.</p> <h2>Landing, site vitrine, e-commerce : quel format pour quel besoin ?</h2> <p>Le bon format dépend de ce que le site doit faire pour vous : présenter une offre, rassurer avant un appel, ou vendre directement en ligne.</p> <table class="table-article"> <thead><tr><th>Format</th><th>Pour qui</th><th>Prix DIGITA</th><th>Délai</th></tr></thead> <tbody> <tr><td>Landing Essentielle (une page)</td><td>Une offre, un événement, un premier pas sur le web</td><td>499 €</td><td>5 jours ouvrés</td></tr> <tr><td>Landing Page en 48 h (LP48)</td><td>Une page de vente rédigée pour vous, avec formulaire ou paiement</td><td>997 €</td><td>48 h ouvrées</td></tr> <tr><td>Site vitrine (offre 974)</td><td>Artisans, cabinets, commerces qui veulent être trouvés et contactés</td><td>990 € d''identité visuelle (690 € si vous avez déjà un logo), puis 49 €/mois</td><td>5 jours ouvrés à 4 semaines</td></tr> <tr><td>Boutique en ligne</td><td>Vendre des produits avec paiement sécurisé et gestion des stocks</td><td>À partir de 2 490 €</td><td>Sur devis</td></tr> </tbody> </table> <p>Pour la plupart des TPE de l''île, le site vitrine suffit au départ : quelques pages claires, vos réalisations, votre zone d''intervention et un moyen simple de vous joindre. La boutique en ligne se justifie quand vous avez un catalogue et une logistique d''expédition prête.</p> <h2>Les frais qui reviennent chaque année</h2> <p>Le prix affiché sur le devis n''est que la première année. Pour comparer deux offres, additionnez ce que le site vous coûtera sur deux ou trois ans.</p> <ul> <li><strong>Le nom de domaine</strong> : une adresse en .re (l''extension de La Réunion) ou en .fr se renouvelle chaque année. Ces deux extensions sont gérées par l''<a href="https://www.afnic.fr/" target="_blank" rel="noopener">Afnic</a>.</li> <li><strong>L''hébergement</strong> : le serveur qui affiche votre site. Il est parfois inclus dans la maintenance, parfois facturé à part.</li> <li><strong>La maintenance</strong> : mises à jour de sécurité, sauvegardes et petites modifications. Sans elle, un site vieillit vite et peut être piraté.</li> <li><strong>Les outils payants</strong> : prise de rendez-vous, module de réservation ou thème premium ont souvent leur propre abonnement.</li> </ul> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un pisciniste à Saint-Pierre</p> <p>Il a déjà un logo et veut un site de cinq pages : accueil, réalisations, services, zone d''intervention et contact. Avec l''offre 974, il paie 690 € la première fois, puis 49 €/mois de maintenance sur 12 mois, soit 588 €. Sa première année lui coûte donc 1 278 €, hébergement et nom de domaine compris la première année.</p> </div> <h2>Les 5 pièges à repérer dans un devis</h2> <ol> <li><strong>Le nom de domaine au nom du prestataire.</strong> Si vous changez d''agence, vous risquez de perdre votre adresse. Exigez qu''il soit enregistré à votre nom.</li> <li><strong>Un site enfermé dans un outil.</strong> Certains sites ne peuvent pas être déplacés chez un autre hébergeur. Demandez si vous récupérez le code et les contenus.</li> <li><strong>Pas de version mobile soignée.</strong> Vos clients vous cherchent souvent depuis leur téléphone : testez les réalisations du prestataire sur le vôtre.</li> <li><strong>Les obligations légales oubliées.</strong> Mentions légales, politique de confidentialité et gestion des cookies sont obligatoires. La <a href="https://www.cnil.fr/fr/cookies-et-autres-traceurs" target="_blank" rel="noopener">CNIL</a> et <a href="https://entreprendre.service-public.fr/vosdroits/F31228" target="_blank" rel="noopener">Service Public Entreprendre</a> détaillent les règles.</li> <li><strong>Un engagement long sans contenu précis.</strong> Un abonnement de 24 ou 36 mois doit dire clairement ce qui est fait chaque mois.</li> </ol> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Avec l''offre 974, nous créons, hébergeons et maintenons votre site vitrine. Vous payez l''identité visuelle une fois (990 €, ou 690 € si vous avez un logo), puis 49 €/mois sur 12 mois. Le nom de domaine est offert la première année, Analytics et la Search Console sont branchés, et vous restez propriétaire du domaine, des contenus et du code.</p> <p><a href="/services#sites-web" class="encadre-lien">Voir l''offre Sites web</a> · <a href="/tarifs" class="encadre-lien">Comparer les tarifs</a></p> </div> <h2>Questions fréquentes</h2> <h3>Combien coûte un site vitrine à La Réunion ?</h3> <p>Le prix dépend du nombre de pages, des contenus à créer et de la maintenance incluse. Chez DIGITA, un site vitrine démarre à 990 € d''identité visuelle (690 € si vous avez déjà un logo), puis 49 €/mois de maintenance sur 12 mois, hébergement compris.</p> <h3>Faut-il payer chaque mois pour un site internet ?</h3> <p>Le nom de domaine et l''hébergement se paient chaque année, quel que soit le prestataire. La maintenance mensuelle n''est pas obligatoire, mais sans mises à jour ni sauvegardes, un site devient lent, vulnérable et finit par disparaître des résultats de Google.</p> <h3>Combien de temps faut-il pour créer un site ?</h3> <p>Une page de vente simple peut être en ligne en 48 heures à 5 jours ouvrés. Un site vitrine prend de 5 jours ouvrés à 4 semaines, selon le nombre de pages et la rapidité avec laquelle les textes et photos sont validés.</p> <h3>Le nom de domaine m''appartient-il ?</h3> <p>Il doit être enregistré à votre nom, c''est le premier point à vérifier sur un devis. Chez DIGITA, vous possédez le domaine, les contenus et le code de votre site, même si vous changez de prestataire.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.afnic.fr/" target="_blank" rel="noopener">Afnic</a> : registre des noms de domaine en .fr et .re.</li> <li><a href="https://www.cnil.fr/fr/cookies-et-autres-traceurs" target="_blank" rel="noopener">CNIL : site web, cookies et autres traceurs</a>.</li> <li><a href="https://entreprendre.service-public.fr/vosdroits/F31228" target="_blank" rel="noopener">Service Public Entreprendre : gérer les cookies sur le site d''une entreprise</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 7 novembre 2026.</li> </ul> </div>', 'Prix d''un site internet à La Réunion : le vrai coût', 'Combien coûte un site internet à La Réunion ? Landing, site vitrine, e-commerce : les vrais prix, les frais annuels et les pièges à repérer avant de signer.', 'prix site internet Réunion, site vitrine 974, création site internet La Réunion, tarif site web', '/assets/images/blog/prix-site-internet-reunion.webp', '/assets/images/blog/prix-site-internet-reunion.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Instagram ou Facebook : où sont vos clients à La Réunion ?', 'instagram-ou-facebook-reunion', (SELECT id FROM service_categories WHERE slug = 'reseaux-sociaux'), 'Réseaux sociaux', 'Avant de publier tous les jours partout, vérifiez où votre clientèle passe son temps. La méthode pour le mesurer vous-même, gratuitement, en une heure.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Il n''y a pas de bonne réponse universelle : la clientèle d''un institut de beauté et celle d''un plombier n''utilisent pas les réseaux de la même façon.</li> <li>Vous pouvez mesurer gratuitement où se trouve votre clientèle, avec les outils de Meta et une simple question posée à vos clients.</li> <li>Un seul réseau tenu chaque semaine rapporte plus que deux comptes abandonnés après un mois.</li> </ul> </div> <p>Publier tous les jours sur Facebook, Instagram et TikTok à la fois : c''est le conseil qu''on entend partout, et c''est le plus sûr moyen d''abandonner au bout de trois semaines. Pour une TPE réunionnaise, le temps est la ressource la plus rare. La vraie question n''est donc pas « faut-il être partout ? », mais « où mes clients passent-ils leur temps ? ».</p> <p>Bonne nouvelle : vous n''avez pas besoin d''une étude de marché pour le savoir. Voici une méthode en quatre étapes, gratuite, que vous pouvez faire en une heure.</p> <h2>Étape 1 : estimer votre audience avec le gestionnaire de publicités</h2> <p>Le gestionnaire de publicités de Meta affiche une estimation du nombre de personnes que vous pouvez toucher, avant même de dépenser un euro. C''est l''outil le plus précis pour comparer Facebook et Instagram sur votre zone.</p> <ol> <li>Créez une campagne sans la publier (vous ne paierez rien tant qu''elle n''est pas lancée).</li> <li>Dans l''audience, choisissez « La Réunion », ou seulement les communes que vous desservez.</li> <li>Indiquez l''âge et, si besoin, les centres d''intérêt de votre clientèle type.</li> <li>Dans les placements, cochez seulement Facebook, notez l''estimation, puis faites de même avec seulement Instagram.</li> </ol> <p>Vous obtenez deux ordres de grandeur, propres à votre cible. Ce sont des estimations de Meta, pas des chiffres exacts, mais elles suffisent pour voir si un réseau domine nettement chez vos clients.</p> <h2>Étape 2 : regarder les statistiques que vous avez déjà</h2> <p>Si vous avez déjà une page Facebook ou un compte Instagram, ouvrez les statistiques dans <a href="https://www.facebook.com/business/tools/meta-business-suite" target="_blank" rel="noopener">Meta Business Suite</a>. Trois chiffres comptent :</p> <ul> <li><strong>La ville et l''âge de vos abonnés</strong> : correspondent-ils à votre clientèle réelle ?</li> <li><strong>Les publications qui ont le plus de réactions</strong> : photos de chantier, coulisses, promotions, conseils ?</li> <li><strong>Les messages reçus</strong> : c''est le meilleur signal. Un réseau qui vous envoie des demandes vaut plus qu''un réseau qui vous envoie des « j''aime ».</li> </ul> <h2>Étape 3 : demander à vos clients</h2> <p>C''est la méthode la plus simple et la plus oubliée. Pendant un mois, demandez à chaque nouveau client : « Comment nous avez-vous connus ? ». Notez la réponse dans un carnet ou un tableau. Bouche-à-oreille, Google, Facebook, Instagram, panneau sur le chantier : au bout de quelques semaines, vous saurez où investir votre temps.</p> <h2>Étape 4 : observer vos concurrents</h2> <p>Regardez les comptes des entreprises de votre secteur à La Réunion. Lesquels publient régulièrement ? Lesquels reçoivent des commentaires de clients, et pas seulement de leurs proches ? La <a href="https://www.facebook.com/ads/library/" target="_blank" rel="noopener">bibliothèque publicitaire de Meta</a> montre aussi, gratuitement, les publicités actuellement diffusées par n''importe quelle page.</p> <h2>Facebook ou Instagram : la grille de décision</h2> <p>En attendant vos propres mesures, voici les tendances habituelles selon le type d''activité. À confirmer avec les étapes ci-dessus.</p> <table class="table-article"> <thead><tr><th>Votre activité</th><th>Réseau à tenir en premier</th><th>Pourquoi</th></tr></thead> <tbody> <tr><td>Restaurant, snack, food truck</td><td>Instagram et Facebook</td><td>Le visuel donne envie ; Facebook sert aux horaires, menus et avis.</td></tr> <tr><td>Institut, coiffure, bien-être</td><td>Instagram</td><td>Avant/après, ambiance, prise de rendez-vous par message.</td></tr> <tr><td>Gîte, activité touristique</td><td>Instagram, puis la fiche Google</td><td>Les visiteurs cherchent des photos avant de réserver.</td></tr> <tr><td>Artisan, BTP, dépannage</td><td>Facebook et la fiche Google</td><td>Les groupes locaux et les recommandations entre voisins y circulent.</td></tr> <tr><td>Services aux entreprises</td><td>LinkedIn et Facebook</td><td>Les décideurs y cherchent des partenaires de confiance.</td></tr> </tbody> </table> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une esthéticienne au Tampon</p> <p>Elle publie sur Facebook depuis deux ans, sans résultat. En un mois de « Comment nous avez-vous connues ? », la moitié de ses nouvelles clientes répondent Instagram. Elle décide de publier deux fois par semaine sur Instagram (avant/après, coulisses), et de partager automatiquement ces publications sur Facebook depuis Meta Business Suite. Un seul effort, deux réseaux.</p> </div> <h2>Le rythme qui tient dans la durée</h2> <p>Mieux vaut deux publications par semaine pendant un an que dix publications la première semaine. Fixez-vous un rythme que vous pouvez tenir les mois chargés, préparez vos publications à l''avance et programmez-les. Et parlez comme vous parlez à vos clients : un mot de créole, une photo de votre quartier ou de votre équipe crée plus de proximité qu''un visuel générique.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Nous créons, planifions et publions vos contenus, et répondons aux commentaires. Formule Essentiel : 1 réseau et 8 publications par mois pour 390 €/mois. Formule Pro : 2 réseaux et 12 à 16 publications pour 590 €/mois. Vous démarrez de zéro ? Le Pack de lancement (logo et page Facebook professionnelle) coûte 499 €.</p> <p><a href="/services#reseaux-sociaux" class="encadre-lien">Voir l''offre Réseaux sociaux</a> · <a href="/solutions#lancement" class="encadre-lien">Le Pack de lancement</a></p> </div> <h2>Questions fréquentes</h2> <h3>Faut-il être sur tous les réseaux sociaux ?</h3> <p>Non. Une petite entreprise gagne à bien tenir un ou deux réseaux, choisis selon sa clientèle, plutôt qu''à ouvrir des comptes partout et les laisser vides. Un compte abandonné donne une image négative à ceux qui le découvrent.</p> <h3>Combien de fois par semaine faut-il publier ?</h3> <p>Deux publications par semaine, tenues dans la durée, suffisent pour une TPE. La régularité compte plus que la quantité : choisissez un rythme que vous pouvez tenir même pendant les périodes chargées.</p> <h3>Peut-on publier en même temps sur Facebook et Instagram ?</h3> <p>Oui. Meta Business Suite permet de créer une publication et de la diffuser sur les deux réseaux à la fois, et de la programmer à l''avance. Adaptez seulement le format de l''image et le texte si besoin.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.facebook.com/business/tools/meta-business-suite" target="_blank" rel="noopener">Meta Business Suite</a> : statistiques et programmation des publications.</li> <li><a href="https://www.facebook.com/ads/library/" target="_blank" rel="noopener">Bibliothèque publicitaire de Meta</a>.</li> <li><a href="https://www.facebook.com/business/help/714656935225188" target="_blank" rel="noopener">Meta : se préparer à faire de la publicité</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 7 novembre 2026.</li> </ul> </div>', 'Instagram ou Facebook : où sont vos clients en 974 ?', 'Facebook ou Instagram pour votre entreprise à La Réunion ? Une méthode gratuite en 4 étapes pour savoir où sont vos clients, et quel rythme tenir.', 'community manager Réunion, Facebook entreprise 974, Instagram commerce La Réunion, réseaux sociaux TPE', '/assets/images/blog/instagram-ou-facebook-reunion.webp', '/assets/images/blog/instagram-ou-facebook-reunion.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Pub Facebook à La Réunion : quel budget pour démarrer ?', 'budget-publicite-facebook-reunion', (SELECT id FROM service_categories WHERE slug = 'publicite-en-ligne'), 'Publicité', '5 € par jour, est-ce assez ? La méthode pour calculer votre budget à rebours, le tester 2 à 4 semaines et savoir enfin ce que vous coûte un client.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Il n''existe pas de budget idéal : il se calcule à partir du nombre de demandes que vous voulez recevoir et de ce qu''une demande vous coûte réellement.</li> <li>Ce coût, seul un test le donne : 2 à 4 semaines avec un petit budget, deux ou trois publicités, et un seul objectif.</li> <li>Pour démarrer, nous conseillons 300 à 500 € par mois de budget publicitaire, versés directement à Meta.</li> </ul> </div> <p>« J''ai mis 50 € sur une publication boostée, ça n''a rien donné. » Cette phrase, beaucoup de commerçants et d''artisans de l''île l''ont prononcée. Le problème vient rarement du montant. Il vient de la méthode : pas d''objectif précis, une audience trop large, et un jugement rendu au bout de trois jours.</p> <p>Ce guide vous donne une méthode pour fixer votre budget de départ, le tester sans gaspiller, puis décider d''augmenter ou d''arrêter.</p> <h2>Ce que vous achetez vraiment avec une publicité Facebook</h2> <p>Sur Facebook et Instagram, vous n''achetez pas un emplacement à prix fixe comme une affiche. Vous participez à des enchères : chaque fois qu''une personne de votre cible ouvre l''application, Meta choisit quelles publicités lui montrer. Le prix dépend donc de votre audience, de la concurrence sur cette audience et de la qualité de votre publicité.</p> <p>Conséquence directe : personne ne peut vous dire à l''avance combien coûtera un client. Un prestataire qui vous garantit un coût par contact avant le moindre test vous vend une promesse, pas une méthode.</p> <h2>Calculer votre budget à rebours</h2> <p>Partez de votre objectif, pas d''un montant au hasard. Le calcul tient en une ligne :</p> <p class="formule">Budget mensuel = nombre de demandes visées × coût d''une demande</p> <p>Le nombre de demandes, vous le connaissez : combien de devis ou de rendez-vous en plus pouvez-vous absorber chaque mois ? Le coût d''une demande, en revanche, vous ne le connaîtrez qu''après un test. C''est pour cela que la première étape est toujours une phase de test à budget limité.</p> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif, chiffres hypothétiques) : un cuisiniste à Saint-Denis</p> <p>Il veut 10 demandes de devis de plus par mois. Il teste 300 € sur 3 semaines et reçoit 15 demandes : une demande lui coûte donc 20 €. Pour atteindre son objectif, il lui faut environ 200 € par mois. Si le test avait donné 60 € par demande, il aurait su qu''il fallait revoir l''offre ou la page avant d''augmenter le budget.</p> </div> <h2>La phase de test, étape par étape</h2> <ol> <li><strong>Un seul objectif.</strong> Demandes de devis, messages ou appels : choisissez l''action qui compte pour vous, et réglez la campagne sur cet objectif plutôt que sur les « j''aime ».</li> <li><strong>Une zone réaliste.</strong> Ciblez les communes où vous intervenez vraiment. Inutile de payer pour toucher Saint-Benoît si vous ne vous déplacez pas au-delà de Saint-Pierre.</li> <li><strong>Deux ou trois publicités.</strong> Une photo de réalisation, une courte vidéo, une offre claire. Laissez Meta répartir le budget vers celle qui fonctionne.</li> <li><strong>Ne touchez à rien pendant une semaine.</strong> Meta explique que chaque nouvel ensemble de publicités passe par une <a href="https://www.facebook.com/business/help/112167992830700" target="_blank" rel="noopener">phase d''apprentissage</a> pendant laquelle les résultats sont instables. Le modifier tous les jours la relance.</li> <li><strong>Répondez vite.</strong> Une demande qui attend une réponse jusqu''au lendemain est souvent perdue. La publicité ne sert à rien si personne ne décroche.</li> </ol> <h2>Les spécificités de La Réunion</h2> <ul> <li><strong>Une audience limitée.</strong> L''île compte moins d''habitants qu''une grande métropole : les mêmes personnes voient vite vos publicités plusieurs fois. Renouvelez vos visuels toutes les 3 à 4 semaines pour éviter la lassitude.</li> <li><strong>Un calendrier qui n''est pas celui de la métropole.</strong> Les vacances scolaires de La Réunion suivent leur propre calendrier, publié par l''<a href="https://www.ac-reunion.fr/" target="_blank" rel="noopener">académie de La Réunion</a>, et le 20 décembre est férié. Calez vos campagnes sur ces dates, pas sur celles de Paris.</li> <li><strong>La saison des pluies et des cyclones.</strong> De janvier à mars, certaines activités ralentissent. Prévoyez de baisser ou de suspendre le budget plutôt que de payer pendant une alerte.</li> </ul> <h2>Booster une publication ou passer par le gestionnaire ?</h2> <p>Le bouton « Booster » est pratique pour donner de la visibilité à une publication. Mais le <a href="https://www.facebook.com/business/help/347839548598012" target="_blank" rel="noopener">boost</a> offre moins de réglages que le gestionnaire de publicités : objectifs, placements et tests y sont plus limités. Pour obtenir des demandes de devis ou des rendez-vous, le gestionnaire de publicités est l''outil adapté.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Nous créons vos publicités (visuels, textes, vidéos courtes), testons à petit budget puis amplifions ce qui fonctionne. La gestion coûte 290 €/mois pour un budget publicitaire jusqu''à 1 000 €/mois, versé directement à Meta, sans engagement au-delà d''un mois. Pas de site ? Nous créons une page d''atterrissage dédiée.</p> <p><a href="/services#publicite" class="encadre-lien">Voir l''offre Publicité</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Quel budget minimum pour une publicité Facebook ?</h3> <p>Meta accepte de petits budgets quotidiens, mais un budget trop faible ne permet pas d''apprendre quoi que ce soit. Pour une TPE réunionnaise, 300 à 500 € par mois de budget publicitaire permettent un vrai test sur 2 à 4 semaines.</p> <h3>Combien de temps avant de voir des résultats ?</h3> <p>Les premières demandes arrivent souvent dans les premiers jours, mais il faut compter 2 à 6 semaines pour savoir ce que coûte réellement un contact et quelles publicités fonctionnent.</p> <h3>Faut-il un site internet pour faire de la publicité ?</h3> <p>Non. Une publicité peut renvoyer vers un formulaire intégré à Facebook, vers Messenger ou vers un appel. Une page d''atterrissage dédiée aide toutefois à convaincre les prospects qui veulent en savoir plus avant de vous contacter.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.facebook.com/business/help/112167992830700" target="_blank" rel="noopener">Meta : à propos de la phase d''apprentissage</a>.</li> <li><a href="https://www.facebook.com/business/help/347839548598012" target="_blank" rel="noopener">Meta : booster une publication depuis votre page</a>.</li> <li><a href="https://www.facebook.com/business/help/203183363050448" target="_blank" rel="noopener">Meta : bonnes pratiques sur les budgets minimums</a>.</li> <li><a href="https://www.ac-reunion.fr/" target="_blank" rel="noopener">Académie de La Réunion</a> : calendrier scolaire.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 7 novembre 2026.</li> </ul> </div>', 'Pub Facebook à La Réunion : quel budget pour démarrer ?', 'Quel budget pour une publicité Facebook à La Réunion ? La méthode pour le calculer, tester sans gaspiller et décider d''augmenter ou d''arrêter.', 'publicité Facebook Réunion, budget pub Meta 974, Facebook Ads La Réunion, publicité Instagram', '/assets/images/blog/budget-publicite-facebook-reunion.webp', '/assets/images/blog/budget-publicite-facebook-reunion.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Automatiser ses devis : le guide pour les artisans réunionnais', 'automatiser-devis-artisan', (SELECT id FROM service_categories WHERE slug = 'intelligence-artificielle'), 'Automatisation', 'Un devis envoyé le lendemain a déjà un concurrent. Du formulaire à la signature en ligne, comment gagner vos soirées sans changer de métier.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Automatiser ses devis ne veut pas dire laisser une machine fixer vos prix : on automatise la saisie, l''envoi et les relances, pas votre expertise.</li> <li>Un circuit simple tient en cinq étapes : demande structurée, fiche client, devis brouillon, signature en ligne, relances automatiques.</li> <li>Bonus : depuis le 1er septembre 2026, toutes les entreprises doivent pouvoir recevoir des factures électroniques, et les TPE devront en émettre à partir du 1er septembre 2027. C''est le bon moment pour remettre de l''ordre dans vos outils.</li> </ul> </div> <p>Il est 21 h, la journée de chantier est finie, et il reste trois devis à taper. Le client de mardi attend toujours le sien. Pour beaucoup d''artisans réunionnais, le devis est la tâche qui déborde sur les soirées et les week-ends. Et pendant ce temps, le prospect a parfois déjà signé ailleurs.</p> <p>La bonne nouvelle : la plus grande partie de ce travail est répétitive, donc automatisable. Ce guide vous montre comment, sans changer de métier ni de façon de travailler.</p> <h2>Ce qu''on automatise, et ce qui reste à vous</h2> <p>Un devis, c''est d''un côté votre savoir-faire (comprendre le besoin, évaluer le chantier, fixer le prix) et de l''autre beaucoup de manipulations : recopier les coordonnées, retrouver les tarifs, mettre en page, envoyer, relancer. C''est ce deuxième bloc qu''on automatise.</p> <table class="table-article"> <thead><tr><th>Tâche</th><th>Automatisable ?</th><th>Comment</th></tr></thead> <tbody> <tr><td>Recueillir la demande</td><td>Oui</td><td>Formulaire en ligne avec les bonnes questions et l''envoi de photos</td></tr> <tr><td>Créer la fiche client</td><td>Oui</td><td>Transfert automatique du formulaire vers votre tableau ou votre CRM</td></tr> <tr><td>Préparer le devis</td><td>En partie</td><td>Brouillon prérempli à partir de vos prestations et prix habituels</td></tr> <tr><td>Fixer le prix final</td><td>Non</td><td>Vous relisez, ajustez et validez</td></tr> <tr><td>Envoyer et faire signer</td><td>Oui</td><td>Envoi par e-mail avec signature électronique</td></tr> <tr><td>Relancer</td><td>Oui</td><td>Messages programmés tant que le devis n''est ni signé ni refusé</td></tr> <tr><td>Visite technique</td><td>Non</td><td>Le rendez-vous peut être pris en ligne, la visite reste humaine</td></tr> </tbody> </table> <h2>Le circuit en 5 étapes</h2> <ol class="etapes"> <li><strong>La demande arrive déjà complète.</strong> Au lieu d''un « Bonjour, c''est pour un devis » sur WhatsApp, le client remplit un formulaire : type de travaux, commune, surface ou quantité, délai souhaité, photos. Vous savez tout de suite si le chantier vous intéresse.</li> <li><strong>La fiche client se crée toute seule.</strong> Nom, téléphone, adresse et détails du projet arrivent dans votre tableau de suivi ou votre CRM, avec une alerte sur votre téléphone. Plus de papier volant ni de message perdu.</li> <li><strong>Le devis est prérempli.</strong> À partir de vos prestations types (pose au mètre carré, forfait de déplacement, fournitures), un brouillon est préparé dans votre logiciel de devis. Il ne vous reste qu''à vérifier et ajuster.</li> <li><strong>Le client signe en ligne.</strong> Le devis part par e-mail avec un lien de signature électronique. Le client peut signer depuis son téléphone, le soir même.</li> <li><strong>Les relances partent automatiquement.</strong> Sans réponse après quelques jours, un message de relance poli part tout seul, puis un second une semaine plus tard. Dès que le devis est signé, les relances s''arrêtent et la facture peut être préparée à partir du devis.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un électricien à Saint-Paul</p> <p>Il reçoit ses demandes par téléphone, Messenger et WhatsApp, et prépare ses devis le dimanche. Avec un formulaire relié à son logiciel de devis, chaque demande arrive avec photos et adresse, le brouillon est prêt quand il ouvre son ordinateur, et les relances partent sans qu''il y pense. Il garde la main sur chaque prix, mais n''a plus rien à recopier.</p> </div> <h2>Quels outils utiliser ?</h2> <p>Inutile de tout remplacer. Dans la plupart des cas, on relie les outils que vous avez déjà.</p> <ul> <li><strong>Pour la demande</strong> : un formulaire sur votre site, ou un formulaire Google si vous n''avez pas de site.</li> <li><strong>Pour le suivi</strong> : un Google Sheets bien organisé suffit pour démarrer ; un CRM devient utile au-delà de quelques dizaines de demandes par mois.</li> <li><strong>Pour les devis et factures</strong> : un logiciel de facturation (Pennylane, Sellsy ou équivalent) qui gère les modèles, la signature et le passage du devis à la facture.</li> <li><strong>Pour relier le tout</strong> : un outil d''automatisation comme n8n, Make ou Zapier, qui fait passer les informations d''un outil à l''autre sans ressaisie.</li> </ul> <h2>Facture électronique : une raison de plus de s''y mettre maintenant</h2> <p>Depuis le 1er septembre 2026, toutes les entreprises établies en France et assujetties à la TVA doivent être capables de recevoir des factures électroniques. L''obligation d''en émettre s''appliquera aux PME et aux micro-entreprises à partir du 1er septembre 2027, selon <a href="https://entreprendre.service-public.fr/vosdroits/F23208" target="_blank" rel="noopener">Service Public Entreprendre</a>. La Réunion applique la TVA : les entreprises de l''île sont concernées par ce calendrier.</p> <p>Si vous tapez encore vos devis et factures dans un traitement de texte, vous devrez de toute façon changer d''outil d''ici là. Autant choisir dès maintenant un logiciel compatible et en profiter pour automatiser le circuit complet. Le site des <a href="https://www.impots.gouv.fr/professionnel/je-passe-la-facturation-electronique" target="_blank" rel="noopener">impôts</a> détaille les démarches.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Nous branchons vos outils (Gmail, Google Sheets, agenda, CRM, WhatsApp Business, logiciel de devis) pour que la demande, le devis et les relances s''enchaînent sans ressaisie. Un scénario simple, d''un outil vers un autre, coûte 490 €, payé une fois ; les outils eux-mêmes coûtent en général 10 à 30 €/mois. Mise en place en 1 à 3 semaines, testée et documentée.</p> <p><a href="/services#ia-automation" class="encadre-lien">Voir l''offre Automatisation</a> · <a href="/outils/roi-calculator" class="encadre-lien">Calculer le temps gagné</a></p> </div> <h2>Questions fréquentes</h2> <h3>Faut-il changer de logiciel pour automatiser ses devis ?</h3> <p>Pas forcément. Si votre logiciel de devis permet les modèles et l''envoi par e-mail, on peut souvent le relier à un formulaire et à un outil de relance. Un changement devient utile si vous faites encore vos devis dans un traitement de texte, surtout avec l''arrivée de la facture électronique.</p> <h3>Les devis automatiques fixent-ils les prix à ma place ?</h3> <p>Non. Le système prépare un brouillon à partir de vos prestations et prix habituels, mais c''est vous qui relisez, ajustez et validez chaque devis avant l''envoi. Votre expertise reste au centre.</p> <h3>La facture électronique concerne-t-elle les micro-entrepreneurs ?</h3> <p>Oui. Selon Service Public Entreprendre, l''obligation concerne aussi les entreprises en franchise de TVA, comme les micro-entrepreneurs : réception depuis le 1er septembre 2026, émission à partir du 1er septembre 2027 pour les PME et micro-entreprises.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://entreprendre.service-public.fr/vosdroits/F23208" target="_blank" rel="noopener">Service Public Entreprendre : tout savoir sur la facturation</a>, vérifié le 7 août 2026.</li> <li><a href="https://www.impots.gouv.fr/professionnel/je-passe-la-facturation-electronique" target="_blank" rel="noopener">impots.gouv.fr : je passe à la facturation électronique</a>.</li> <li><a href="https://entreprendre.service-public.fr/vosdroits/F10029" target="_blank" rel="noopener">Service Public Entreprendre : délais de conservation des documents</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 7 novembre 2026.</li> </ul> </div>', 'Automatiser ses devis : le guide pour les artisans', 'Formulaire, devis prérempli, signature en ligne, relances : comment un artisan automatise ses devis sans perdre la main, avant la facture électronique de 2027.', 'automatiser devis artisan, relance devis automatique, facture électronique 2027, automatisation TPE Réunion', '/assets/images/blog/automatiser-devis-artisan.webp', '/assets/images/blog/automatiser-devis-artisan.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Agent IA : répondre à vos clients 24 h/24, est-ce utile pour une TPE ?', 'agent-ia-repondre-clients-24h', (SELECT id FROM service_categories WHERE slug = 'intelligence-artificielle'), 'Agents IA', 'Le message arrive à 23 h, vous le voyez le lendemain à midi, le client a signé ailleurs. Ce qu''un agent IA change, et comment savoir s''il est fait pour vous.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Un agent IA répond à vos clients par écrit (et parfois au téléphone) à toute heure, à partir de vos propres informations : services, tarifs, horaires, zone d''intervention.</li> <li>Il est utile si vous recevez des messages en dehors de vos horaires, souvent les mêmes questions, ou des demandes de rendez-vous que vous ne pouvez pas traiter sur le moment.</li> <li>Depuis le 2 août 2026, la loi européenne sur l''IA impose que vos clients sachent qu''ils échangent avec une IA. Un bon agent le dit dès le premier message, et passe la main à un humain quand il le faut.</li> </ul> </div> <p>Un message Messenger arrive à 23 h : « Bonjour, vous faites les terrasses en bois ? Vous passez sur Saint-Leu ? » Vous le voyez le lendemain à midi, entre deux chantiers. Vous répondez le soir. Le prospect, lui, a écrit à trois entreprises en même temps, et la première qui a répondu a obtenu le rendez-vous.</p> <p>C''est exactement le problème qu''un agent IA résout. Mais ce n''est pas une baguette magique, et ce n''est pas utile à toutes les entreprises. Voici comment savoir si c''est fait pour vous.</p> <h2>Agent IA, chatbot : quelle différence ?</h2> <p>Le chatbot classique fonctionne avec des boutons et des réponses écrites à l''avance : « Tapez 1 pour les horaires, 2 pour les tarifs ». Dès que la question sort du script, il bloque.</p> <p>Un agent IA comprend les questions formulées librement, avec les fautes de frappe, les abréviations ou un mot de créole. Il répond à partir des informations que vous lui avez données, peut poser des questions pour qualifier la demande, et réaliser une action : proposer un créneau, créer une fiche client, vous envoyer une alerte.</p> <h2>Ce qu''un agent IA sait faire</h2> <ul> <li><strong>Répondre tout de suite, 24 h/24</strong>, sur Messenger, Instagram, votre site ou au téléphone.</li> <li><strong>Parler de votre entreprise</strong> : il est entraîné sur vos services, vos tarifs, votre zone et votre façon de parler.</li> <li><strong>Qualifier la demande</strong> : type de projet, commune, budget, délai. Vous recevez un résumé clair, pas une conversation à relire.</li> <li><strong>Poser un rendez-vous</strong> directement dans votre agenda, sur les créneaux que vous avez ouverts.</li> <li><strong>Vous prévenir</strong> par SMS ou e-mail à chaque nouvelle demande, et créer la fiche dans votre CRM.</li> </ul> <h2>Ce qu''il ne doit pas faire</h2> <p>Un agent bien conçu connaît ses limites. Il ne s''engage pas sur un prix qui demande une visite, ne traite pas seul une réclamation sensible et ne donne pas de conseil médical ou juridique. Dans ces cas, il le dit clairement au client et vous transmet la conversation. C''est une règle à fixer dès le départ, et à vérifier pendant les tests.</p> <h2>Est-ce utile pour votre entreprise ?</h2> <p>Comptez les « oui » :</p> <ul class="checklist"> <li>Vous recevez des messages le soir, le week-end ou pendant que vous êtes sur un chantier.</li> <li>On vous pose souvent les mêmes questions : horaires, zone, prix de départ, délais.</li> <li>Une partie de vos clients écrit depuis la métropole, avec 2 à 3 heures de décalage.</li> <li>Vous prenez des rendez-vous, et le téléphone sonne quand vous ne pouvez pas décrocher.</li> <li>Vous avez déjà perdu un client parce qu''un concurrent a répondu plus vite.</li> </ul> <p>Trois « oui » ou plus : un agent IA peut vous faire gagner du temps et des clients. Un ou deux : commencez par les réponses automatiques gratuites décrites ci-dessous.</p> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un gîte à Cilaos</p> <p>La plupart des demandes viennent de métropole, souvent tard le soir à l''heure de La Réunion. L''agent répond aux questions sur l''accès, les équipements et les disponibilités, propose les dates libres et transmet à la propriétaire les demandes de réservation déjà qualifiées. Elle répond le matin à des clients qui ont déjà toutes les informations.</p> </div> <h2>Par où commencer, gratuitement</h2> <p>Avant d''investir, activez les outils gratuits déjà intégrés à vos applications. <a href="https://business.whatsapp.com/" target="_blank" rel="noopener">WhatsApp Business</a> propose un message d''accueil, un message d''absence et des réponses rapides. Meta Business Suite offre des réponses automatiques similaires pour Messenger et Instagram. Si ces messages simples vous font déjà gagner du temps, un agent IA ira beaucoup plus loin.</p> <h2>Les règles à respecter</h2> <ul> <li><strong>Dire que c''est une IA.</strong> L''<a href="https://artificialintelligenceact.eu/fr/article/50/" target="_blank" rel="noopener">article 50 du règlement européen sur l''IA</a> impose que les personnes soient informées qu''elles interagissent avec un système d''IA. Cette obligation s''applique depuis le 2 août 2026.</li> <li><strong>Protéger les données.</strong> Les conversations contiennent des noms, des numéros, des adresses : le RGPD s''applique. La <a href="https://www.cnil.fr/fr/intelligence-artificielle" target="_blank" rel="noopener">CNIL</a> publie ses recommandations sur l''IA. Privilégiez des modèles hébergés en Europe ou utilisés sous contrat strict.</li> <li><strong>Tester avant d''ouvrir.</strong> Un agent se teste à huis clos, avec de vraies questions, avant d''être mis en ligne. Et vous devez pouvoir relire ses conversations à tout moment.</li> </ul> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>INES, notre agent IA, répond à vos clients sur Messenger et Instagram jour et nuit, qualifie leur projet et pose le rendez-vous dans votre agenda. Il est entraîné sur vos informations et testé à huis clos avant la mise en ligne, et ses conversations restent visibles. Offre Standardiste Messenger &amp; Insta 24/7 : mise en service de 490 € à 890 €, puis 149 € à 249 €/mois, jusqu''à 300 conversations par mois.</p> <p><a href="/agent24-7" class="encadre-lien">Découvrir INES</a> · <a href="https://agent24-7.digita.buzz" class="encadre-lien" target="_blank" rel="noopener">La tester en direct</a></p> </div> <h2>Questions fréquentes</h2> <h3>Mes clients sauront-ils qu''ils parlent à une IA ?</h3> <p>Oui, et c''est obligatoire depuis le 2 août 2026 en application du règlement européen sur l''IA. Un bon agent se présente comme un assistant automatique dès le premier message, ce qui n''empêche pas une conversation naturelle et chaleureuse.</p> <h3>Que se passe-t-il si l''agent ne sait pas répondre ?</h3> <p>Il le dit au client, prend ses coordonnées et vous transmet la demande avec une alerte par SMS ou e-mail. Les règles de transfert vers un humain sont fixées avec vous avant la mise en ligne.</p> <h3>Combien coûte un agent IA pour une petite entreprise ?</h3> <p>Il faut compter une mise en service puis un abonnement mensuel. Chez DIGITA, l''offre Standardiste Messenger et Instagram coûte de 490 € à 890 € de mise en service, puis de 149 € à 249 € par mois selon le paramétrage, jusqu''à 300 conversations par mois.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://artificialintelligenceact.eu/fr/article/50/" target="_blank" rel="noopener">Règlement européen sur l''IA, article 50 : obligations de transparence</a> (texte officiel : <a href="https://eur-lex.europa.eu/eli/reg/2024/1689/oj" target="_blank" rel="noopener">règlement (UE) 2024/1689</a>).</li> <li><a href="https://www.cnil.fr/fr/intelligence-artificielle" target="_blank" rel="noopener">CNIL : intelligence artificielle</a>.</li> <li><a href="https://business.whatsapp.com/" target="_blank" rel="noopener">WhatsApp Business</a> : messages automatiques.</li> <li>Offres DIGITA : <a href="/solutions">page Solutions</a>, consultée le 7 novembre 2026.</li> </ul> </div>', 'Agent IA : répondre à vos clients 24 h/24', 'Un agent IA répond à vos clients jour et nuit et prend leurs rendez-vous. Ce qu''il sait faire, ses limites, les règles à respecter, et s''il vous sera utile.', 'agent IA entreprise, chatbot Messenger, réponse automatique clients, assistant IA TPE Réunion', '/assets/images/blog/agent-ia-repondre-clients-24h.webp', '/assets/images/blog/agent-ia-repondre-clients-24h.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;
